from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    background = Counter(v for row in g for v in row).most_common(1)[0][0]
    div_rows = {r for r in range(h) if g[r][0] != background and all(v == g[r][0] for v in g[r])}
    div_cols = {c for c in range(w) if g[0][c] != background and all(g[r][c] == g[0][c] for r in range(h))}
    if not div_rows and not div_cols:
        return g
    rb = [-1] + sorted(div_rows) + [h]
    cb = [-1] + sorted(div_cols) + [w]
    row_ranges = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    col_ranges = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    panels = [(a, b, x, y) for a, b in row_ranges for x, y in col_ranges]
    source = max(panels, key=lambda p: sum(g[r][c] != background for r in range(p[0], p[1]) for c in range(p[2], p[3])))
    a, b, x, y = source
    tile = [g[r][x:y] for r in range(a, b)]
    for r0, r1, c0, c1 in panels:
        if (r0, r1, c0, c1) == source:
            continue
        for r in range(r0, r1):
            for c in range(c0, c1):
                g[r][c] = tile[r-r0][c-c0]
    return g
